PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE geonames ( featureid integer primary key autoincrement not null, name text, asciiname text, latitude real, longitude real, feature_class text, feature_code text, country_code text, admin1_code text, population int default null, elevation int default null, timezone text, usercode int default 0 );
CREATE TABLE geonames_aliases ( featureid int, alias text );
CREATE TABLE timezones ( name text primary key, country_code text, offset real );
CREATE TABLE featurecodes ( feature_class text,  feature_code text,  description1 text, description2 text );
CREATE TABLE admincodes ( country text, admin1code text, name text, asciiname text );
CREATE TABLE countries ( iso text primary key, name text not null, capital text, area int, population int, continent text not null );
CREATE VIEW atlas as SELECT g.featureid as id, g.name as name, g.country_code, g.admin1_code, g.latitude, g.longitude, g.population FROM geonames g;
CREATE VIEW atlas_ascii as SELECT g.featureid as id, g.asciiname as name, g.country_code, g.admin1_code, g.latitude, g.longitude, g.population FROM geonames g;
CREATE VIEW atlas_alias as SELECT a.featureid as id, a.alias as name, g.country_code, g.admin1_code, g.latitude, g.longitude, g.population FROM geonames_aliases a, geonames g WHERE a.featureid = g.featureid;
CREATE INDEX geonames_name on geonames( name );
CREATE INDEX geonames_asciiname on geonames( asciiname );
CREATE INDEX geonames_aliases_featureid on geonames_aliases( featureid );
CREATE INDEX geonames_aliases_alias on geonames_aliases( alias );
CREATE UNIQUE INDEX timezones_name on timezones( name );
CREATE INDEX timezones_country_code on timezones( country_code );
CREATE UNIQUE INDEX featurecodes_pk on featurecodes( feature_class, feature_code );
CREATE UNIQUE INDEX admincodes_code on admincodes( country, admin1code );
CREATE UNIQUE INDEX countries_iso on countries( iso );
COMMIT;
